	@Test
	void ownerReusesBoundSourceAcrossMissingAndEmptyKeysAndRetainsAdmission() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_000_000L, 1_000_000L);
		BoundFixture fixture = new BoundFixture();
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelProjectionCursor.Owner owner = KernelProjectionCursor.Owner.open(ledger, 3)) {
			assertNotNull(owner);
			long retained = ledger.usedBytes();
			assertTrue(retained > 0L);
			BoundRunCursor bound = fixture.openBoundRunCursor();
			try {
				KernelProjectionCursor.Source firstSource = null;
				KernelProjectionCursor firstCursor = null;
				for (long root : new long[] { 1L, 3L, 2L, 4L, 1L }) {
					KernelProjectionCursor.Source source = KernelProjectionCursor.probe(owner, bound, root);
					if (firstSource == null) {
						firstSource = source;
					} else {
						assertSame(firstSource, source, "one producer site must retain one source adapter");
					}
					CollectingProgram program = new CollectingProgram();
					KernelProjectionCursor cursor = activate(owner, source, program, true, false, -1L,
							false, null);
					assertNotNull(cursor);
					if (firstCursor == null) {
						firstCursor = cursor;
					} else {
						assertSame(firstCursor, cursor, "one producer site must retain one physical projection cursor");
					}
					List<Binding> rows = drain(cursor, program);
					int expected = root == 1L ? 3 : root == 4L ? 1 : 0;
					assertEquals(expected, rows.size(), "missing and empty runs must produce no rows");
					assertEquals(retained, ledger.usedBytes(), "activation close must retain the owner admission");
				}
				assertEquals(5, fixture.binds);
				assertEquals(1, fixture.opens);
				assertEquals(0, fixture.closes, "the owner borrows the ordinary source cursor");
				owner.close();
				assertEquals(0L, ledger.usedBytes(), "final owner disposal must release retained admission");
				assertEquals(0, fixture.closes, "the caller still owns the borrowed bound cursor");
			} finally {
				bound.close();
			}
		}
		assertEquals(1, fixture.closes);
	}

	@Test
	void reusedCursorResetsContextSelectionPerActivation() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_000_000L, 1_000_000L);
		BoundFixture fixture = new BoundFixture();
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelProjectionCursor.Owner owner = KernelProjectionCursor.Owner.open(ledger, 0)) {
			BoundRunCursor bound = fixture.openBoundRunCursor();
			try {
				KernelProjectionCursor.Source source = KernelProjectionCursor.probe(owner, bound, 1L);
				CollectingProgram filtered = new CollectingProgram();
				KernelProjectionCursor first = activate(owner, source, filtered, true, true, 7L, true, null);
				List<Binding> named = drain(first, filtered);
				assertEquals(List.of(new Binding(1L, 101L, 7L), new Binding(1L, 102L, 7L)), named);

				KernelProjectionCursor.Source secondSource = KernelProjectionCursor.probe(owner, bound, 1L);
				assertSame(source, secondSource);
				CollectingProgram allContexts = new CollectingProgram();
				KernelProjectionCursor second = activate(owner, secondSource, allContexts, true, false, -1L, false,
						null);
				assertSame(first, second);
				assertEquals(List.of(new Binding(1L, 101L, 0L), new Binding(1L, 101L, 7L),
						new Binding(1L, 102L, 7L)), drain(second, allContexts));
			} finally {
				bound.close();
			}
		}
	}

	@Test
	void activeRebindIsRejectedBeforeChangingTheActiveSource() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_000_000L, 1_000_000L);
		BoundFixture fixture = new BoundFixture();
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelProjectionCursor.Owner owner = KernelProjectionCursor.Owner.open(ledger, 0)) {
			BoundRunCursor bound = fixture.openBoundRunCursor();
			try {
				KernelProjectionCursor.Source activeSource = KernelProjectionCursor.probe(owner, bound, 1L);
				CollectingProgram activeProgram = new CollectingProgram();
				KernelProjectionCursor active = activate(owner, activeSource, activeProgram, true, false, -1L,
						false, null);
				assertThrows(IllegalStateException.class, () -> KernelProjectionCursor.probe(owner, bound, 4L));
				assertEquals(1, fixture.binds, "rejected rebind must not mutate the active source");
				assertEquals(List.of(new Binding(1L, 101L, 0L), new Binding(1L, 101L, 7L),
						new Binding(1L, 102L, 7L)), drain(active, activeProgram));

				KernelProjectionCursor.Source nextSource = KernelProjectionCursor.probe(owner, bound, 4L);
				assertSame(activeSource, nextSource);
				CollectingProgram nextProgram = new CollectingProgram();
				assertEquals(List.of(new Binding(4L, 401L, 9L)), drain(
						activate(owner, nextSource, nextProgram, true, false, -1L, false, null), nextProgram));
			} finally {
				bound.close();
			}
		}
	}

