	@Test
	void cancellationExceptionAndEarlyCloseReleaseTheReusablePhysicalCursor() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_000_000L, 1_000_000L);
		BoundFixture fixture = new BoundFixture();
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelProjectionCursor.Owner owner = KernelProjectionCursor.Owner.open(ledger, 0)) {
			long retained = ledger.usedBytes();
			BoundRunCursor bound = fixture.openBoundRunCursor();
			try {
				KernelCancellation cancellation = new KernelCancellation(Long.MAX_VALUE);
				cancellation.cancel();
				CollectingProgram cancelledProgram = new CollectingProgram();
				KernelProjectionCursor cancelled = activate(owner, KernelProjectionCursor.probe(owner, bound, 1L),
						cancelledProgram, true, false, -1L, false, cancellation);
				assertThrows(KernelCancelledException.class, cancelled::advance);
				cancelled.closeActivation();
				assertEquals(retained, ledger.usedBytes());

				CollectingProgram failingProgram = new CollectingProgram(KernelProjectionCursor.ROOT);
				KernelProjectionCursor failing = activate(owner, KernelProjectionCursor.probe(owner, bound, 1L),
						failingProgram, true, false, -1L, false, null);
				assertThrows(IllegalStateException.class, failing::advance);
				failing.closeActivation();
				assertEquals(retained, ledger.usedBytes());

				CollectingProgram earlyProgram = new CollectingProgram();
				KernelProjectionCursor early = activate(owner, KernelProjectionCursor.probe(owner, bound, 1L),
						earlyProgram, true, false, -1L, false, null);
				early.closeActivation();
				assertEquals(retained, ledger.usedBytes());

				CollectingProgram recoveredProgram = new CollectingProgram();
				List<Binding> recovered = drain(
						activate(owner, KernelProjectionCursor.probe(owner, bound, 4L), recoveredProgram, true, false,
								-1L,
								false, null),
						recoveredProgram);
				assertEquals(List.of(new Binding(4L, 401L, 9L)), recovered);
			} finally {
				bound.close();
			}
			owner.close();
			assertEquals(0L, ledger.usedBytes());
		}
	}

