		private final long[][] contexts = { { 1L, 2L }, {} };
		int rowOpens;
		int rowCloses;

		@Override
		public long find(long node) {
			return node == 1L ? 1L : node == 2L ? 2L : NodePredicates.NOT_FOUND;
		}

		@Override
		public long rowSize(long rowHandle) {
			return rowHandle > 0L ? 1L : 0L;
		}

		@Override
		public int copyRow(long node, long rowHandle, long fromOffset, int length, long[] predicateTarget,
				int predicateOffset, long[] runTarget, int runOffset) {
			if (fromOffset > 0L || length == 0 || rowHandle <= 0L) {
				return 0;
			}
			predicateTarget[predicateOffset] = 10L;
			runTarget[runOffset] = rowHandle;
			return 1;
		}

		@Override
		public PredicateRowCursor openRow(long node) {
			rowOpens++;
			long rowHandle = find(node);
			return new PredicateRowCursor() {
				private boolean emitted;

				@Override
				public boolean advance() {
					if (emitted || rowHandle == NodePredicates.NOT_FOUND) {
						return false;
					}
					emitted = true;
					return true;
				}

				@Override
				public long predicate() {
					return 10L;
				}

				@Override
				public long runHandle() {
					return rowHandle;
				}

				@Override
				public long work() {
					return emitted ? 1L : 0L;
				}

				@Override
				public void close() {
					rowCloses++;
				}
			};
		}

		@Override
		public long size(long runHandle) {
			return run(runHandle).length;
		}

		@Override
		public long neighborAt(long runHandle, long runOffset) {
			return run(runHandle)[Math.toIntExact(runOffset)];
		}

		@Override
		public long contextAt(long runHandle, long runOffset) {
			return contextRun(runHandle)[Math.toIntExact(runOffset)];
		}

		private long[] run(long handle) {
			return neighbors[Math.toIntExact(handle - 1L)];
		}

